  const nextRevenue = (await database.db.select().from(schema.accountingItems).where(and(eq(schema.accountingItems.deploymentId, business.id), eq(schema.accountingItems.kind, 'revenue')))).find(item => item.id !== revenue.id)!;
  await database.db.update(schema.accountingItems).set({ occurredAt: new Date(boundary.endsAt.getTime() + 86400000) }).where(eq(schema.accountingItems.id, nextRevenue.id));
  await database.updatePayment(nextRevenue.paymentId!, { paidAt: new Date(boundary.endsAt.getTime() + 86400000) });
  const nextTax = await financial.recordAccountingItem(admin, { deploymentId: business.id, kind: 'tax', amount: '0.00', currency: 'USD', occurredAt: new Date(boundary.endsAt.getTime() + 86400000), sourceProvider: 'controlled-document', sourceReference: 'next-week-zero-tax-reviewed', evidence: { taxAssessment: 'Fixture explicit zero tax; not a production convention.' } });
  await financial.verifyAccountingItem(admin, nextTax, false);
